        [Fact]
        public void Test_Issue396BackticksBlankLineAfterFence()
        {
            // Backticks code block trims trailing newline inside fence and adds blank line after closing fence (issue #396)
            var result = HtmlToMarkdownConverter.Convert("<p>Foo</p><pre><code>1\n2\n</code></pre><p>Bar</p>", new ConversionOptions { CodeBlockStyle = CodeBlockStyle.Backticks });
            Assert.Equal("Foo\n\n```\n1\n2\n```\n\nBar\n", result.Content);

        }

