            var result = HtmlToMarkdownConverter.Convert("<p>Before <img src=\"data:image/png;base64,AAAA\" alt=\"icon\"> after</p>", new ConversionOptions { InlineDataMedia = JsonSerializer.Deserialize<InlineDataMedia>("\"DropElement\"", ConfigOptions)! });
            Assert.Equal("Before after\n", result.Content);

        }

        [Fact]
        public void Test_OptionsInlineDataMediaKeepDefault()
        {
            // Keep writes an inline data image with its payload
            var result = HtmlToMarkdownConverter.Convert("<p>Before <img src=\"data:image/png;base64,AAAA\" alt=\"icon\"> after</p>", new ConversionOptions { InlineDataMedia = JsonSerializer.Deserialize<InlineDataMedia>("\"Keep\"", ConfigOptions)! });
            Assert.Contains("![icon](data:image/png;base64,AAAA)", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsInlineDataMediaRealAddressWins()
        {
            // A real lazy-load address wins over an inline data src when the payload is not kept
            var result = HtmlToMarkdownConverter.Convert("<p><img src=\"data:image/png;base64,AAAA\" data-src=\"https://example.com/real.png\" alt=\"icon\"></p>", new ConversionOptions { InlineDataMedia = JsonSerializer.Deserialize<InlineDataMedia>("\"DropElement\"", ConfigOptions)! });
            Assert.Equal("![icon](https://example.com/real.png)\n", result.Content);

        }

        [Fact]
        public void Test_OptionsKeepInlineImagesInParagraph()
        {
            // Images inside specified tags stay inline
            var result = HtmlToMarkdownConverter.Convert("<p>Text <img src='icon.png' alt='icon'> more text</p>", new ConversionOptions { KeepInlineImagesIn = new List<string>() { "p" } });
            Assert.Contains("Text", result.Content.ToString());
            Assert.Contains("more text", result.Content.ToString());

        }

        [Fact]
