            var result = HtmlToMarkdownConverter.Convert("<div><p>Shallow</p><div><div><div><p>Too deep</p></div></div></div></div>", new ConversionOptions { MaxDepth = 3 });
            Assert.Contains("Shallow", result.Content.ToString());
            Assert.DoesNotContain("Too deep", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsMaxDepthZeroEmpty()
        {
