        [Fact]
        public void Test_OptionsOutputFormatDjot()
        {
            // Djot output format produces djot-compatible markup
            var result = HtmlToMarkdownConverter.Convert("<p>Simple paragraph.</p>", new ConversionOptions { OutputFormat = OutputFormat.Djot });
            Assert.True(((object?)result.Content) switch
