        [Fact]
        public void Test_OptionsOutputFormatMarkdown()
        {
            // Default markdown output format produces standard markdown
            var result = HtmlToMarkdownConverter.Convert("<h1>Title</h1><p>Some text.</p>", new ConversionOptions { HeadingStyle = HeadingStyle.Atx, OutputFormat = OutputFormat.Markdown });
            Assert.Contains("# Title", result.Content.ToString());
            Assert.Contains("Some text.", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsOutputFormatPlain()
        {
            // Plain text output format strips markdown syntax
            var result = HtmlToMarkdownConverter.Convert("<h1>Title</h1><p>Some <strong>bold</strong> text.</p>", new ConversionOptions { OutputFormat = OutputFormat.Plain });
            Assert.Contains("Title", result.Content.ToString());
            Assert.Contains("bold", result.Content.ToString());
            Assert.Contains("text.", result.Content.ToString());
            Assert.DoesNotContain("**bold**", result.Content.ToString());
            Assert.DoesNotContain("# Title", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsPreprocessingAggressive()
        {
            // Aggressive preset removes nav, footer, aside unconditionally
            var result = HtmlToMarkdownConverter.Convert("<nav>Menu</nav><article><h1>Title</h1><p>Content</p></article><aside>Sidebar</aside><footer>Footer</footer>", new ConversionOptions { Preprocessing = new PreprocessingOptions { Preset = JsonSerializer.Deserialize<PreprocessingPreset>("\"Aggressive\"", ConfigOptions)! } });
            Assert.Contains("Title", result.Content.ToString());
            Assert.Contains("Content", result.Content.ToString());
            Assert.DoesNotContain("Menu", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsPreprocessingEnabledFalseSkipsCleanup()
        {
            // Disabling preprocessing entirely preserves elements the standard preset would remove
            var result = HtmlToMarkdownConverter.Convert("<nav>NavSection</nav><p>Paragraph</p>", new ConversionOptions { Preprocessing = new PreprocessingOptions { Enabled = false } });
            Assert.Contains("NavSection", result.Content.ToString());
            Assert.Contains("Paragraph", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsPreprocessingMinimal()
        {
            // Minimal preset preserves nav, footer, aside
            var result = HtmlToMarkdownConverter.Convert("<nav>Navigation</nav><p>Content</p><footer>Footer</footer>", new ConversionOptions { Preprocessing = new PreprocessingOptions { Preset = JsonSerializer.Deserialize<PreprocessingPreset>("\"Minimal\"", ConfigOptions)! } });
            Assert.Contains("Navigation", result.Content.ToString());
            Assert.Contains("Content", result.Content.ToString());
            Assert.Contains("Footer", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsPreprocessingRemoveForms()
        {
            // Forms are removed when remove_forms is true
            var result = HtmlToMarkdownConverter.Convert("<p>Before</p><form><input type='text'/><button>Submit</button></form><p>After</p>", new ConversionOptions { Preprocessing = new PreprocessingOptions { RemoveForms = true } });
            Assert.Contains("Before", result.Content.ToString());
            Assert.Contains("After", result.Content.ToString());
            Assert.DoesNotContain("Submit", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsPreprocessingRemoveNavigationFalseKeepsNav()
        {
            // Setting remove_navigation to false preserves nav and aside elements
            var result = HtmlToMarkdownConverter.Convert("<nav>SiteMenu</nav><main><p>MainContent</p></main><aside>SidebarText</aside>", new ConversionOptions { Preprocessing = new PreprocessingOptions { RemoveNavigation = false } });
            Assert.Contains("SiteMenu", result.Content.ToString());
            Assert.Contains("MainContent", result.Content.ToString());
            Assert.Contains("SidebarText", result.Content.ToString());

        }

        [Fact]
