        [Fact]
        public void Test_OptionsStrongEmUnderscore()
        {
            // Strong and em tags use underscore symbol instead of asterisk
            var result = HtmlToMarkdownConverter.Convert("<p><strong>bold</strong> and <em>italic</em></p>", new ConversionOptions { StrongEmSymbol = "_" });
            Assert.Contains("__bold__", result.Content.ToString());
            Assert.Contains("_italic_", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsSubSymbolTilde()
        {
            // Subscript rendered with tilde symbol
            var result = HtmlToMarkdownConverter.Convert("<p>H<sub>2</sub>O</p>", new ConversionOptions { SubSymbol = "~" });
            Assert.Contains("~2~", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsSupSymbolCaret()
        {
            // Superscript rendered with caret symbol
            var result = HtmlToMarkdownConverter.Convert("<p>x<sup>2</sup></p>", new ConversionOptions { SupSymbol = "^" });
            Assert.Contains("^2^", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsUrlEscapeStyleAngleDefault()
        {
            // Default angle style wraps URLs containing spaces in angle brackets
            var result = HtmlToMarkdownConverter.Convert("<a href=\"/file (1).pdf\">file</a>", new ConversionOptions { UrlEscapeStyle = UrlEscapeStyle.Angle });
            Assert.Contains("</file (1).pdf>", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsUrlEscapeStylePercentAngleBracketsInUrl()
        {
            // Percent style encodes angle brackets in link URLs from issue 392
            var result = HtmlToMarkdownConverter.Convert("<a href=\"/file (1) <draft>.pdf\">file</a>", new ConversionOptions { UrlEscapeStyle = UrlEscapeStyle.Percent });
            Assert.Contains("/file%20%281%29%20%3Cdraft%3E.pdf", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsUrlEscapeStylePercentImage()
        {
            // Percent style encodes special characters in image src URLs
            var result = HtmlToMarkdownConverter.Convert("<img src=\"/img (1) <draft>.png\" alt=\"alt\">", new ConversionOptions { UrlEscapeStyle = UrlEscapeStyle.Percent });
            Assert.Contains("/img%20%281%29%20%3Cdraft%3E.png", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsUrlEscapeStylePercentLink()
        {
            // Percent style encodes spaces and parens in link URLs
            var result = HtmlToMarkdownConverter.Convert("<a href=\"/file (1).pdf\">file</a>", new ConversionOptions { UrlEscapeStyle = UrlEscapeStyle.Percent });
            Assert.Contains("/file%20%281%29.pdf", result.Content.ToString());
            Assert.DoesNotContain("</", result.Content.ToString());

        }

        [Fact]
        public void Test_OptionsWhitespaceNormalized()
        {
            // Normalized whitespace mode collapses multiple spaces
            var result = HtmlToMarkdownConverter.Convert("<p>Text   with    extra   spaces.</p>", new ConversionOptions { WhitespaceMode = WhitespaceMode.Normalized });
            Assert.True(((object?)result.Content) switch
            {
                null => false,
                string text => text.Length > 0,
                System.Collections.ICollection items => items.Count > 0,
                _ => true,
            }, "expected non-empty value");
            Assert.Contains("Text", result.Content.ToString());
            Assert.Contains("with", result.Content.ToString());
            Assert.Contains("extra", result.Content.ToString());
            Assert.Contains("spaces.", result.Content.ToString());

        }

